test('normal Instant Send explicitly accelerates its queued operation once and removes Undo without claiming provider Sent',async()=>{
 const app=await mount('Only this queued message');try{await app.click('Send');assert.equal(app.host.querySelector('[aria-label="Message body"]'),null);await app.click('Instant Send');const operation=app.getComposerOperation();assert.equal(operation.state,'queued');assert.ok(operation.accelerationId);assert.match(app.host.querySelector('.composer-send-toast')?.textContent||'',/Send accelerated!/);assert.equal([...app.host.querySelectorAll('button')].some(button=>button.textContent==='Undo'),false);assert.equal(app.host.querySelector('button[aria-label="Instant Send"]'),null);await app.key('z');assert.equal(app.requests.filter(request=>request.path==='/api/delivery-accelerations'&&request.method==='POST').length,1);assert.equal(app.requests.filter(request=>request.path.endsWith('/send-operations')&&request.method==='POST').length,1);assert.equal(app.requests.some(request=>request.path.endsWith('/cancel')&&request.method==='POST'),false);assert.equal(operation.providerMessageId,null)}finally{await app.close()}
});

