const cloudTime='2026-10-28T00:00:00.000Z';
function providerAppFixture(initialBody='Managed authored body',options:{blank?:boolean;syncPatch?:boolean}={}){
 let record:any={id:'synthetic-draft',accountId:'demo',to:options.blank?'':'one@example.test, two@example.test',cc:'',bcc:'',subject:options.blank?'':'Managed subject',body:initialBody,html:'<div>'+initialBody+'</div>',attachments:[],revision:1,status:'draft',createdAt:cloudTime,updatedAt:cloudTime};
 let snapshot:any={accountId:'demo',draftId:record.id,ownership:'replica-new',revision:1,state:'idle',desiredRevision:1,desiredHash:'a'.repeat(64),syncedRevision:null,syncedHash:null,providerDraftId:null,providerMessageId:null,providerThreadId:null,operation:null,error:null,deliveryBlocked:false};
 let heldPatch:ReturnType<typeof deferred<void>>|null=null,heldStatus:ReturnType<typeof deferred<Response>>|null=null,discardMode:'pending'|'unknown'|'terminal'|'refused'='pending',receipt:any=null,discardPost:any=null;
 const cloudSynced=(revision:number,hash:string)=>({id:'cloud-save-'+revision,accountId:'demo',draftId:record.id,kind:'create',state:'confirmed',draftRevision:revision,contentHash:hash,providerDraftId:null,providerMessageId:null,providerThreadId:null,result:{providerDraftId:'gmail-owned',providerMessageId:'gmail-message-'+revision,providerThreadId:'gmail-thread'},createdAt:cloudTime,issuedAt:cloudTime,completedAt:cloudTime,resolution:'matching-snapshot',error:null});
 const terminal=()=>{const operation={id:receipt.operationId,accountId:'demo',draftId:record.id,kind:'delete',state:'confirmed',draftRevision:snapshot.providerDraftId?snapshot.syncedRevision:receipt.draftRevision,contentHash:snapshot.providerDraftId?snapshot.syncedHash:receipt.contentHash,providerDraftId:snapshot.providerDraftId,providerMessageId:snapshot.providerMessageId,providerThreadId:snapshot.providerThreadId,result:null,createdAt:cloudTime,issuedAt:snapshot.providerDraftId?cloudTime:null,completedAt:cloudTime,resolution:'target-unavailable',error:null};snapshot={...snapshot,revision:snapshot.revision+1,state:'discarded',deliveryBlocked:true,operation};return{providerDraft:snapshot,receipt,resolution:'discarded'}};
 const handler=async(request:Request):Promise<Response|undefined>=>{
  if(request.path==='/api/drafts'&&request.method==='POST')return response({draft:record,providerDraft:snapshot});
  if(request.path==='/api/drafts/synthetic-draft/provider?accountId=demo'){if(heldStatus)return heldStatus.promise;return response({providerDraft:snapshot})}
  if(request.path==='/api/drafts/synthetic-draft'&&request.method==='PATCH'){
   const gate=heldPatch;heldPatch=null;if(gate)await gate.promise;record={...record,...request.body,revision:record.revision+1};const hash=String.fromCharCode(97+record.revision%20).repeat(64);snapshot={...snapshot,revision:snapshot.revision+1,state:'queued',desiredRevision:record.revision,desiredHash:hash,deliveryBlocked:false};
   if(options.syncPatch){const operation=cloudSynced(record.revision,hash);snapshot={...snapshot,state:'synced',syncedRevision:record.revision,syncedHash:hash,providerDraftId:operation.result.providerDraftId,providerMessageId:operation.result.providerMessageId,providerThreadId:operation.result.providerThreadId,operation}}
   return response({draft:record,providerDraft:snapshot});
  }
  if(request.path==='/api/drafts/synthetic-draft/discard-operations'&&request.method==='POST'){
   discardPost=request.body;if(discardMode==='refused')return response({error:{code:'provider_draft_revision_conflict',message:'Reviewed discard changed'}},409);
   receipt={id:'owned-discard-receipt',accountId:'demo',draftId:record.id,clientRequestId:request.body.clientRequestId,operationId:'owned-delete',draftRevision:request.body.expectedDraftRevision,contentHash:request.body.expectedContentHash,acceptedSyncRevision:request.body.expectedSyncRevision,acceptedAt:cloudTime};
   snapshot={...snapshot,revision:snapshot.revision+1,state:'discard_queued',deliveryBlocked:true};if(discardMode==='unknown')throw Error('Discard acknowledgement lost');return response(discardMode==='terminal'?terminal():{providerDraft:snapshot,receipt,resolution:'pending'},202);
  }
  if(request.path.startsWith('/api/draft-discard-operations/by-request/'))return response(discardMode==='terminal'?terminal():{providerDraft:snapshot,receipt,resolution:'pending'});
  return undefined;
 };
 return{fixture:{google:true,draftPatch:record,providerRequest:handler} as AppFixture,handler,getRecord:()=>record,getSnapshot:()=>snapshot,getDiscard:()=>discardPost,setDiscardMode:(mode:typeof discardMode)=>{discardMode=mode},holdPatch:()=>heldPatch=deferred<void>(),holdStatus:()=>heldStatus=deferred<Response>(),setSnapshot:(value:any)=>{snapshot=value}};
}

