async function keyboardHelpFromSubject(app:Awaited<ReturnType<typeof mount>>){
 const subject=app.host.querySelector<HTMLInputElement>('input[aria-label="Subject"]');assert.ok(subject);await act(async()=>subject.focus());await recipientKey(app,'k',{metaKey:true});const command=app.host.querySelector<HTMLInputElement>('input[aria-label="Superhuman Command"]');assert.ok(command);await fillInput(command,'Shortcuts');const result=[...app.host.querySelectorAll<HTMLButtonElement>('.command-results button')].find(b=>b.textContent?.trim()==='Shortcuts');assert.ok(result);await act(async()=>result.click());const dialog=app.host.querySelector<HTMLElement>('[role="dialog"][aria-label="shortcuts"]');assert.ok(dialog);for(let i=0;i<40&&!dialog.contains(window.document.activeElement);i++)await act(async()=>new Promise(r=>setTimeout(r,2)));assert.equal(dialog.contains(window.document.activeElement),true);return subject;
}
