async function openAutoDrafts(app:Awaited<ReturnType<typeof mount>>){
 if(!app.host.querySelector('.settings-list'))await app.click('Settings');await app.click('Auto Drafts');
 for(let i=0;i<50&&!app.host.querySelector('.auto-drafts-dialog input[data-auto-drafts-field]');i++)await act(async()=>new Promise(r=>setTimeout(r,2)));
 const dialog=app.host.querySelector<HTMLElement>('.auto-drafts-dialog');assert.ok(dialog);return dialog;
}
