 const reply='Confirmed: Thursday at 3 pm in Room Maple. <img src="https://outside.example.test">',quote='On Thu, Oct 29, 2026, Fictional sender wrote:\n> Can you confirm Thursday at 3 pm in Room Maple?';
 let draft={id:'synthetic-draft',accountId:'demo',threadId:thread.id,to:'work@example.test',cc:'',bcc:'',subject:'Re: Fictional Cedar question',body:reply+'\n\n'+quote,html:'<div>Confirmed: Thursday at 3 pm in Room Maple. &lt;img src="https://outside.example.test"&gt;</div><div>On Thu, Oct 29, 2026, Fictional sender wrote:</div><blockquote>Can you confirm Thursday at 3 pm in Room Maple?</blockquote>',attachments:[],status:'draft',revision:0,updatedAt:'2026-10-29T00:00:01.000Z'};
 const p={quotedBody:{quoteStartUtf8:new TextEncoder().encode(reply).length+2},bindingVersion:'a'.repeat(64),generationId:'00000001-0000-4000-8000-000000000000',sourceRef:'00000002-0000-4000-8000-000000000000',inputVersion:'b'.repeat(64),sourceMessageId:message.id,targetRef:'00000003-0000-4000-8000-000000000000',targetVersion:'c'.repeat(64),publishedAt:'2026-10-29T00:00:01.000Z',contentHash:await autoDraftsDigest(autoDraftStable({to:draft.to,cc:draft.cc,bcc:draft.bcc,subject:draft.subject,body:draft.body,html:draft.html,attachments:draft.attachments}))};
