function doneAck(request:Request,state='confirmed',thread?:unknown){const id=decodeURIComponent(request.path.match(/\/threads\/([^/]+)/)![1]),b=request.body,undoId=state==='confirmed'?'undo-'+b.clientRequestId:null;return{...(thread?{thread}:{}),undoId,receipt:{version:1,clientRequestId:b.clientRequestId,accountId:b.accountId,accountVersion:b.accountVersion,threadId:id,action:'archive',state,undoId,reason:state==='refused'?'source-changed':null}}}
const mailRows=(app:Awaited<ReturnType<typeof mount>>)=>[...app.host.querySelectorAll<HTMLElement>('.mail-row[role="button"]')];
test('Done rapid repeated E reserves and advances before first ACK while leaving rows cannot capture selection or click',async()=>{const held=deferred<void>();let rows=[row('one',1),row('two',2),row('three',3),row('four',4)];const issued:string[]=[],app=await mount('',{compose:false,readPage:()=>thinPage(rows),action:async id=>{issued.push(id);if(id==='one')await held.promise;rows=rows.filter(r=>r.id!==id);return{undoId:'undo-'+id}}});try{await act(async()=>{for(let n=0;n<3;n++)window.document.body.dispatchEvent(new window.KeyboardEvent('keydown',{key:'e',repeat:n>0,bubbles:true,cancelable:true}))});assert.equal(focusedId(app.host),'Subject four');assert.deepEqual(mailRows(app).map(n=>n.querySelector('.mail-subject')?.textContent),['Subject four']);assert.equal(app.host.querySelectorAll('[data-done-transition="out"]').length,3);assert.deepEqual(issued,['one']);const leaving=app.host.querySelector<HTMLElement>('[data-done-transition="out"]')!;await act(async()=>{leaving.dispatchEvent(new window.MouseEvent('mouseover',{bubbles:true}));leaving.click()});assert.equal(focusedId(app.host),'Subject four');assert.equal(app.requests.some(r=>/^\/api\/threads\/[^/]+$/.test(r.path)),false);await act(async()=>held.resolve());assert.deepEqual(issued,['one','two','three']);const posts=app.requests.filter(r=>r.method==='POST'&&r.path.endsWith('/actions'));assert.equal(new Set(posts.map(r=>r.body.clientRequestId)).size,3);assert.equal(posts.every(r=>r.body.accountId==='demo'&&r.body.expectedSourceVersion.length===64),true)}finally{held.resolve();await app.close()}});
