test('Shortcuts visual owner keeps the250ms boundary and cancels older frame and retirement work',async context=>{
 context.mock.timers.enable({apis:['setTimeout']});
 const boundary:string[]=[],computed=window.getComputedStyle,frame=globalThis.requestAnimationFrame;
 window.getComputedStyle=(element,pseudo)=>{if(element.classList.contains('shortcuts-overlay')){assert.equal(element.isConnected,true);assert.notEqual((element as HTMLElement).dataset.shortcutsPhase,'open');boundary.push('initial-style')}return computed.call(window,element,pseudo)};
 globalThis.requestAnimationFrame=callback=>{boundary.push('frame');return frame(callback)};
 const {default:ShortcutsOverlay}=await import('../src/ShortcutsOverlay.tsx'),host=window.document.createElement('div');window.document.body.append(host);const root=createRoot(host);let close=0,mounted=true;const ref={current:null as HTMLElement|null};
 const render=(open:boolean)=>act(async()=>root.render(createElement(ShortcutsOverlay,{open,suppressed:false,dialogRef:ref,onClose:()=>close++}))),tick=(ms:number)=>act(async()=>context.mock.timers.tick(ms));
 try{
  await render(true);assert.ok(ref.current);assert.equal(host.querySelector<HTMLElement>('.shortcuts-overlay')?.dataset.shortcutsPhase,'enter');assert.deepEqual(boundary,['initial-style','frame'],'Cold insertion resolves its initial style before arming its frame; this is an ordering check, not browser transition evidence');await tick(0);assert.equal(host.querySelector<HTMLElement>('.shortcuts-overlay')?.dataset.shortcutsPhase,'open');
  await render(false);assert.equal(ref.current,null);assert.ok(host.querySelector('.shortcuts-overlay[inert]'));await tick(249);assert.ok(host.querySelector('.shortcuts-overlay'));await tick(1);assert.equal(host.querySelector('.shortcuts-overlay'),null);
  boundary.length=0;await render(true);assert.deepEqual(boundary,['initial-style','frame'],'A fresh insertion after retirement establishes the same boundary');await tick(0);await render(false);await tick(100);await render(true);await tick(250);assert.ok(ref.current);assert.equal(host.querySelectorAll('[role="dialog"]').length,1);
  await render(false);await act(async()=>root.unmount());mounted=false;await tick(500);assert.equal(host.childElementCount,0);assert.equal(close,0);
 }finally{if(mounted)await act(async()=>root.unmount());window.getComputedStyle=computed;globalThis.requestAnimationFrame=frame;context.mock.timers.reset();host.remove()}
});

test('Shortcuts another modal cannot restart the original retirement clock',async t=>{
 const {default:Overlay}=await import('../src/ShortcutsOverlay.tsx');t.mock.timers.enable({apis:['setTimeout']});
 const host=window.document.createElement('div');window.document.body.append(host);const root=createRoot(host),ref={current:null as HTMLElement|null};let closes=0;
 const render=(open:boolean,suppressed=false)=>act(async()=>root.render(createElement(Overlay,{open,suppressed,dialogRef:ref,onClose:()=>closes++}))),tick=(ms:number)=>act(async()=>t.mock.timers.tick(ms));
 try{
  await render(true);await tick(0);await render(false);await tick(100);await render(false,true);
  const retiring=host.querySelector<HTMLElement>('.shortcuts-overlay')!;assert.ok(retiring);assert.equal(retiring.dataset.shortcutsPhase,'exit');assert.equal(retiring.getAttribute('aria-hidden'),'true');assert.equal(retiring.hasAttribute('inert'),true);assert.equal(host.querySelector('[role="dialog"]'),null);assert.equal(ref.current,null);
  await act(async()=>{retiring.querySelector<HTMLButtonElement>('button')!.click();retiring.dispatchEvent(new window.MouseEvent('mousedown',{bubbles:true}))});assert.equal(closes,0);
  await tick(149);assert.equal(host.querySelectorAll('.shortcuts-overlay').length,1);await tick(1);assert.equal(host.childElementCount,0);
  await render(false,false);assert.equal(host.childElementCount,0);
 }finally{await act(async()=>root.unmount());t.mock.timers.reset();host.remove()}
});

