test('Command handing off to Help does not restore its invoker until the Help actually closes',async()=>{
 const app=await mount('Current Help owns focus');const subject=app.host.querySelector<HTMLInputElement>('input[aria-label="Subject"]')!,focus=subject.focus;let restored=0;try{await act(async()=>subject.focus());await recipientKey(app,'k',{metaKey:true});const input=app.host.querySelector<HTMLInputElement>('input[aria-label="Superhuman Command"]')!;await fillInput(input,'Shortcuts');subject.focus=function(options){restored++;focus.call(subject,options)};await recipientKey(app,'Enter');const help=app.host.querySelector<HTMLElement>('[role="dialog"][aria-label="shortcuts"]')!;assert.ok(help);assert.equal(restored,0,'Command handoff must not restore the old editor');for(let n=0;n<30&&!help.contains(window.document.activeElement);n++)await act(async()=>new Promise(r=>setTimeout(r,2)));assert.ok(help.contains(window.document.activeElement));await recipientKey(app,'Escape');assert.equal(window.document.activeElement,subject);assert.equal(restored,1);assert.equal(app.requests.some(r=>r.method==='POST'&&(r.path.endsWith('/send-operations')||r.path.endsWith('/actions')||r.path.endsWith('/turns'))),false)}finally{subject.focus=focus;await app.close()}
});

