test('Command catalogue initial ten expands on arrows pointer or scroll and stays expanded until reopening',async()=>{
 for(const trigger of ['arrow','pointer','scroll']){const app=await mount('',{compose:false});try{
  await recipientKey(app,'k',{metaKey:true});const input=app.host.querySelector<HTMLInputElement>('input[aria-label="Superhuman Command"]')!,items=()=>[...app.host.querySelectorAll<HTMLButtonElement>('.command-results button')];assert.equal(items().length,10,'initial render is the first ten current results');
  if(trigger==='arrow')await recipientKey(app,'ArrowDown');else await act(async()=>app.host.querySelector('.command-results')!.dispatchEvent(trigger==='pointer'?new window.MouseEvent('mousemove',{bubbles:true}):new window.Event('scroll')));
  const expanded=items().length;assert(expanded>10);assert.equal(items().findIndex(x=>x.classList.contains('active')),trigger==='arrow'?1:0);
  await fillInput(input,'Shortcuts');assert.equal(items().length,1);await fillInput(input,'');assert.equal(items().length,expanded,'query changes retain this mount expansion');await recipientKey(app,'Escape');await recipientKey(app,'k',{metaKey:true});assert.equal(items().length,10,'a fresh Command starts collapsed');assert.equal(app.requests.some(r=>r.method!=='GET'),false);
 }finally{await app.close()}}
});
